using WAID.Application.Abstractions;using WAID.Infrastructure.Diagnostics;namespace WAID.Infrastructure.Tests;public sealed class SecurityPostureTests{private static readonly DateTimeOffset Now=DateTimeOffset.UtcNow;[Fact]public void Capability_matrix_only_flags_confirmed_disabled_controls(){var s=new SecurityPostureSnapshot(Now,[C(SecurityControl.Firewall,SecurityState.Disabled),C(SecurityControl.SecureBoot,SecurityState.Unknown),C(SecurityControl.Tpm,SecurityState.Unavailable),C(SecurityControl.DeviceEncryption,SecurityState.NotApplicable)],false,"Windows",[]);var f=SecurityPostureAnalyzer.Evaluate(s);Assert.Single(f);Assert.Equal(SecurityControl.Firewall,f[0].Control);}[Fact]public void Policy_lock_never_offers_bypass(){var f=Assert.Single(SecurityPostureAnalyzer.Evaluate(new(Now,[C(SecurityControl.Uac,SecurityState.Disabled,true)],true,"Windows",[])));Assert.True(f.PolicyLocked);Assert.Contains("will not bypass",f.RemediationPreview);}[Fact]public void Contradictory_unknown_signal_is_not_disabled(){var f=SecurityPostureAnalyzer.Evaluate(new(Now,[C(SecurityControl.DefenderAntivirus,SecurityState.Unknown)],true,"Windows",[]));Assert.Empty(f);}[Fact]public void Findings_are_non_alarmist_and_explain_prerequisites(){var f=Assert.Single(SecurityPostureAnalyzer.Evaluate(new(Now,[C(SecurityControl.CoreIsolation,SecurityState.Disabled,false,["Virtualization support"])],true,"Windows",[])));Assert.Contains("Windows reports",f.Explanation);Assert.Contains("Virtualization support",f.Prerequisites);}[Fact]public void Non_admin_limitation_preserves_unavailable_state(){var s=new SecurityPostureSnapshot(Now,[C(SecurityControl.SecureBoot,SecurityState.Unavailable)],false,"Windows",["permission unavailable"]);Assert.Empty(SecurityPostureAnalyzer.Evaluate(s));Assert.NotEmpty(s.Limitations);}private static SecurityControlStatus C(SecurityControl c,SecurityState s,bool managed=false,string[]? prereq=null)=>new(c,s,s is not SecurityState.Unavailable,managed,managed?"Policy":"","detail","source",prereq??[]);}
